  str_aircraft_desc_7101001 = "The Colossus can be operated from the Bridge. It has a great view and offers a wide field of vision, and is key to <color=#00F6FF>unlocking access to perks</color>, as well as raising the Mood within the Colossus. Certain Aurorians can also increase the <color=#00F6FF>Mood by furnishing</color> in the Colossus.",
  str_aircraft_desc_7101002 = "The Colossus can be operated from the Bridge. It has a great view and offers a wide field of vision, and is key to <color=#00F6FF>unlocking access to perks</color>, as well as raising the Mood within the Colossus. Certain Aurorians can also increase the <color=#00F6FF>Mood by furnishing</color> in the Colossus.",
  str_aircraft_desc_7101003 = "The Colossus can be operated from the Bridge. It has a great view and offers a wide field of vision, and is key to <color=#00F6FF>unlocking access to perks</color>, as well as raising the Mood within the Colossus. Certain Aurorians can also increase the <color=#00F6FF>Mood by furnishing</color> in the Colossus.",
  str_aircraft_desc_7101004 = "The Colossus can be operated from the Bridge. It has a great view and offers a wide field of vision, and is key to <color=#00F6FF>unlocking access to perks</color>, as well as raising the Mood within the Colossus. Certain Aurorians can also increase the <color=#00F6FF>Mood by furnishing</color> in the Colossus.",
  str_aircraft_desc_7101005 = "The Colossus can be operated from the Bridge. It has a great view and offers a wide field of vision, and is key to <color=#00F6FF>unlocking access to perks</color>, as well as raising the Mood within the Colossus. Certain Aurorians can also increase the <color=#00F6FF>Mood by furnishing</color> in the Colossus.",
  str_aircraft_desc_7102001 = "The Lumina Grid is the power house of the Colossus, <color=#00F6FF>providing lumina for every room</color>. It is also the favorite spot of the Fireflies, thus you can increase your <color=#00F6FF>Firefly recovery speed</color> here. Certain Aurorians are very fond of Fireflies, and can further speed up <color=#00F6FF>Firefly recovery rate</color>.",
  str_aircraft_desc_7102002 = "The Lumina Grid is the power house of the Colossus, <color=#00F6FF>providing lumina for every room</color>. It is also the favorite spot of the Fireflies, thus you can increase your <color=#00F6FF>Firefly recovery speed</color> here. Certain Aurorians are very fond of Fireflies, and can further speed up <color=#00F6FF>Firefly recovery rate</color>.",
  str_aircraft_desc_7102003 = "The Lumina Grid is the power house of the Colossus, <color=#00F6FF>providing lumina for every room</color>. It is also the favorite spot of the Fireflies, thus you can increase your <color=#00F6FF>Firefly recovery speed</color> here. Certain Aurorians are very fond of Fireflies, and can further speed up <color=#00F6FF>Firefly recovery rate</color>.",
  str_aircraft_desc_7102004 = "The Lumina Grid is the power house of the Colossus, <color=#00F6FF>providing lumina for every room</color>. It is also the favorite spot of the Fireflies, thus you can increase your <color=#00F6FF>Firefly recovery speed</color> here. Certain Aurorians are very fond of Fireflies, and can further speed up <color=#00F6FF>Firefly recovery rate</color>.",
  str_aircraft_desc_7102005 = "The Lumina Grid is the power house of the Colossus, <color=#00F6FF>providing lumina for every room</color>. It is also the favorite spot of the Fireflies, thus you can increase your <color=#00F6FF>Firefly recovery speed</color> here. Certain Aurorians are very fond of Fireflies, and can further speed up <color=#00F6FF>Firefly recovery rate</color>.",
  str_aircraft_desc_7103001 = "The <color=#00F6FF>MS on the Luminameter</color> is critical when exploring the Secret Territory. The Artificial Sun here recharges the Luminameter, <color=#00F6FF>providing and restoring MS</color>. Certain Aurorians are particularly passionate about exploring, and can further speed up <color=#00F6FF>the MS recovery rate</color>.",
  str_aircraft_desc_7103002 = "The <color=#00F6FF>MS on the Luminameter</color> is critical when exploring the Secret Territory. The Artificial Sun here recharges the Luminameter, <color=#00F6FF>providing and restoring MS</color>. Certain Aurorians are particularly passionate about exploring, and can further speed up <color=#00F6FF>the MS recovery rate</color>.",
  str_aircraft_desc_7103003 = "The <color=#00F6FF>MS on the Luminameter</color> is critical when exploring the Secret Territory. The Artificial Sun here recharges the Luminameter, <color=#00F6FF>providing and restoring MS</color>. Certain Aurorians are particularly passionate about exploring, and can further speed up <color=#00F6FF>the MS recovery rate</color>.",
  str_aircraft_desc_7103004 = "The <color=#00F6FF>MS on the Luminameter</color> is critical when exploring the Secret Territory. The Artificial Sun here recharges the Luminameter, <color=#00F6FF>providing and restoring MS</color>. Certain Aurorians are particularly passionate about exploring, and can further speed up <color=#00F6FF>the MS recovery rate</color>.",
  str_aircraft_desc_7103005 = "The <color=#00F6FF>MS on the Luminameter</color> is critical when exploring the Secret Territory. The Artificial Sun here recharges the Luminameter, <color=#00F6FF>providing and restoring MS</color>. Certain Aurorians are particularly passionate about exploring, and can further speed up <color=#00F6FF>the MS recovery rate</color>.",
  str_aircraft_desc_7104001 = "You can <color=#00F6FF>manufacture Carriers</color> here at specific time intervals, which reduces the amount of Prism needed to clear the stage and grants your yield immediately when using Sweep. Certain Aurorians even possess Luminatics that can <color=#00F6FF>increase Carrier manufacturing speed</color>.",
  str_aircraft_desc_7104002 = "You can <color=#00F6FF>manufacture Carriers</color> here at specific time intervals, which reduces the amount of Prism needed to clear the stage and grants your yield immediately when using Sweep. Certain Aurorians even possess Luminatics that can <color=#00F6FF>increase Carrier manufacturing speed</color>.",
  str_aircraft_desc_7104003 = "You can <color=#00F6FF>manufacture Carriers</color> here at specific time intervals, which reduces the amount of Prism needed to clear the stage and grants your yield immediately when using Sweep. Certain Aurorians even possess Luminatics that can <color=#00F6FF>increase Carrier manufacturing speed</color>.",
  str_aircraft_desc_7104004 = "You can <color=#00F6FF>manufacture Carriers</color> here at specific time intervals, which reduces the amount of Prism needed to clear the stage and grants your yield immediately when using Sweep. Certain Aurorians even possess Luminatics that can <color=#00F6FF>increase Carrier manufacturing speed</color>.",
  str_aircraft_desc_7104005 = "You can <color=#00F6FF>manufacture Carriers</color> here at specific time intervals, which reduces the amount of Prism needed to clear the stage and grants your yield immediately when using Sweep. Certain Aurorians even possess Luminatics that can <color=#00F6FF>increase Carrier manufacturing speed</color>.",
  str_aircraft_desc_7105001 = "The Prism Pillar is where <color=#00F6FF>Prism is stored</color>, and it also allows you to use Lumina to <color=#00F6FF>gain Prism</color>. The higher your Prism Pillar's level is, the faster you'll accumulate Prism. Advanced Prism Pillars can also <color=#00F6FF>increase your maximum Prism capacity</color>. Certain Aurorians even possess Luminatics that can <color=#00F6FF>improve your Prism acquisition rate</color>.",
  str_aircraft_desc_7105002 = "The Prism Pillar is where <color=#00F6FF>Prism is stored</color>, and it also allows you to use Lumina to <color=#00F6FF>gain Prism</color>. The higher your Prism Pillar's level is, the faster you'll accumulate Prism. Advanced Prism Pillars can also <color=#00F6FF>increase your maximum Prism capacity</color>. Certain Aurorians even possess Luminatics that can <color=#00F6FF>improve your Prism acquisition rate</color>.",
  str_aircraft_desc_7105003 = "The Prism Pillar is where <color=#00F6FF>Prism is stored</color>, and it also allows you to use Lumina to <color=#00F6FF>gain Prism</color>. The higher your Prism Pillar's level is, the faster you'll accumulate Prism. Advanced Prism Pillars can also <color=#00F6FF>increase your maximum Prism capacity</color>. Certain Aurorians even possess Luminatics that can <color=#00F6FF>improve your Prism acquisition rate</color>.",
  str_aircraft_desc_7105004 = "The Prism Pillar is where <color=#00F6FF>Prism is stored</color>, and it also allows you to use Lumina to <color=#00F6FF>gain Prism</color>. The higher your Prism Pillar's level is, the faster you'll accumulate Prism. Advanced Prism Pillars can also <color=#00F6FF>increase your maximum Prism capacity</color>. Certain Aurorians even possess Luminatics that can <color=#00F6FF>improve your Prism acquisition rate</color>.",
  str_aircraft_desc_7105005 = "The Prism Pillar is where <color=#00F6FF>Prism is stored</color>, and it also allows you to use Lumina to <color=#00F6FF>gain Prism</color>. The higher your Prism Pillar's level is, the faster you'll accumulate Prism. Advanced Prism Pillars can also <color=#00F6FF>increase your maximum Prism capacity</color>. Certain Aurorians even possess Luminatics that can <color=#00F6FF>improve your Prism acquisition rate</color>.",
  str_aircraft_desc_7106001 = "The mysterious power of the Starlight Chamber can <color=#00F6FF>create and store Heartstones</color>. The higher your Starlight Chamber's level, the larger and higher its Heartstone storage capacity and manufacturing efficiency will be, and advanced Starlight Chambers will also <color=#00F6FF>provide you with Star Gems</color>. Certain Aurorians even possess Luminatics that can <color=#00F6FF>increase your Heartstone manufacturing efficiency</color>.",
  str_aircraft_desc_7106002 = "The mysterious power of the Starlight Chamber can <color=#00F6FF>create and store Heartstones</color>. The higher your Starlight Chamber's level, the larger and higher its Heartstone storage capacity and manufacturing efficiency will be, and advanced Starlight Chambers will also <color=#00F6FF>provide you with Star Gems</color>. Certain Aurorians even possess Luminatics that can <color=#00F6FF>increase your Heartstone manufacturing efficiency</color>.",
  str_aircraft_desc_7106003 = "The mysterious power of the Starlight Chamber can <color=#00F6FF>create and store Heartstones</color>. The higher your Starlight Chamber's level, the larger and higher its Heartstone storage capacity and manufacturing efficiency will be, and advanced Starlight Chambers will also <color=#00F6FF>provide you with Star Gems</color>. Certain Aurorians even possess Luminatics that can <color=#00F6FF>increase your Heartstone manufacturing efficiency</color>.",
  str_aircraft_desc_7106004 = "The mysterious power of the Starlight Chamber can <color=#00F6FF>create and store Heartstones</color>. The higher your Starlight Chamber's level, the larger and higher its Heartstone storage capacity and manufacturing efficiency will be, and advanced Starlight Chambers will also <color=#00F6FF>provide you with Star Gems</color>. Certain Aurorians even possess Luminatics that can <color=#00F6FF>increase your Heartstone manufacturing efficiency</color>.",
  str_aircraft_desc_7106005 = "The mysterious power of the Starlight Chamber can <color=#00F6FF>create and store Heartstones</color>. The higher your Starlight Chamber's level, the larger and higher its Heartstone storage capacity and manufacturing efficiency will be, and advanced Starlight Chambers will also <color=#00F6FF>provide you with Star Gems</color>. Certain Aurorians even possess Luminatics that can <color=#00F6FF>increase your Heartstone manufacturing efficiency</color>.",
  str_aircraft_desc_7107001 = "Eclipsite Grid, the department of violence, will never spare any Eclipsite walking the earth.",
