  str_aircraft_desc_7107005 = "Eclipsite Grid, the department of violence, will never spare any Eclipsite walking the earth.",
  str_aircraft_desc_7108001 = "Eclipsite Research, an extremely mysterious department, with weird noises constantly coming out of this room. Authorized personnel only.",
  str_aircraft_desc_7108002 = "Eclipsite Research, an extremely mysterious department, with weird noises constantly coming out of this room. Authorized personnel only.",
  str_aircraft_desc_7108003 = "Eclipsite Research, an extremely mysterious department, with weird noises constantly coming out of this room. Authorized personnel only.",
