  str_aircraft_desc_7108005 = "Eclipsite Research, an extremely mysterious department, with weird noises constantly coming out of this room. Authorized personnel only.",
  str_aircraft_desc_7109001 = "The Workshop can <color=#00F6FF>produce and store Atomic Reagents required for smelting</color>, and allows you to consume Atomic Reagents to transform materials. Advanced Workshops provide <color=#00F6FF>larger storage capacity and can smelt high-quality materials</color>. Certain Aurorians have some knowledge about the composition of Atomic Reagents, so they can help to <color=#00F6FF>reduce its consumption</color>.",
  str_aircraft_desc_7109002 = "The Workshop can <color=#00F6FF>produce and store Atomic Reagents required for smelting</color>, and allows you to consume Atomic Reagents to transform materials. Advanced Workshops provide <color=#00F6FF>larger storage capacity and can smelt high-quality materials</color>. Certain Aurorians have some knowledge about the composition of Atomic Reagents, so they can help to <color=#00F6FF>reduce its consumption</color>.",
  str_aircraft_desc_7109003 = "The Workshop can <color=#00F6FF>produce and store Atomic Reagents required for smelting</color>, and allows you to consume Atomic Reagents to transform materials. Advanced Workshops provide <color=#00F6FF>larger storage capacity and can smelt high-quality materials</color>. Certain Aurorians have some knowledge about the composition of Atomic Reagents, so they can help to <color=#00F6FF>reduce its consumption</color>.",
  str_aircraft_desc_7109004 = "The Workshop can <color=#00F6FF>produce and store Atomic Reagents required for smelting</color>, and allows you to consume Atomic Reagents to transform materials. Advanced Workshops provide <color=#00F6FF>larger storage capacity and can smelt high-quality materials</color>. Certain Aurorians have some knowledge about the composition of Atomic Reagents, so they can help to <color=#00F6FF>reduce its consumption</color>.",
  str_aircraft_desc_7109005 = "The Workshop can <color=#00F6FF>produce and store Atomic Reagents required for smelting</color>, and allows you to consume Atomic Reagents to transform materials. Advanced Workshops provide <color=#00F6FF>larger storage capacity and can smelt high-quality materials</color>. Certain Aurorians have some knowledge about the composition of Atomic Reagents, so they can help to <color=#00F6FF>reduce its consumption</color>.",
  str_aircraft_desc_7110001 = "This office on the Colossus specializes in sending Aurorians to towns to handle requests for help. You can dispatch Aurorians to provide assistance via the Sand Table and <color=#00F6FF>earn special rewards</color> in return. Advanced Sand Tables grant you <color=#00F6FF>increased dispatch attempts, allow you to dispatch more teams at the same time, and increase your chances to receive high-rating Dispatch Quests</color>. Some Aurorians excel at managing human resources, speeding up your dispatch attempt recovery rate.",
  str_aircraft_desc_7110002 = "This office on the Colossus specializes in sending Aurorians to towns to handle requests for help. You can dispatch Aurorians to provide assistance via the Sand Table and <color=#00F6FF>earn special rewards</color> in return. Advanced Sand Tables grant you <color=#00F6FF>increased dispatch attempts, allow you to dispatch more teams at the same time, and increase your chances to receive high-rating Dispatch Quests</color>. Some Aurorians excel at managing human resources, speeding up your dispatch attempt recovery rate.",
