  str_aircraft_desc_7110004 = "This office on the Colossus specializes in sending Aurorians to towns to handle requests for help. You can dispatch Aurorians to provide assistance via the Sand Table and <color=#00F6FF>earn special rewards</color> in return. Advanced Sand Tables grant you <color=#00F6FF>increased dispatch attempts, allow you to dispatch more teams at the same time, and increase your chances to receive high-rating Dispatch Quests</color>. Some Aurorians excel at managing human resources, speeding up your dispatch attempt recovery rate.",
  str_aircraft_desc_7110005 = "This office on the Colossus specializes in sending Aurorians to towns to handle requests for help. You can dispatch Aurorians to provide assistance via the Sand Table and <color=#00F6FF>earn special rewards</color> in return. Advanced Sand Tables grant you <color=#00F6FF>increased dispatch attempts, allow you to dispatch more teams at the same time, and increase your chances to receive high-rating Dispatch Quests</color>. Some Aurorians excel at managing human resources, speeding up your dispatch attempt recovery rate.",
  str_aircraft_desc_7111001 = "The Simulation Room is a special facility for Caelestites to improve their commanding skills. You can enter the Command Archives via the command simulator to simulate various environments and battles. The Simulation Room can <color=#00F6FF>create simulated combat scenarios and save the data on special disks</color>. Higher-level Simulation Rooms can <color=#00F6FF>increase the storage limit on Data Disks and decrease production times</color>. Certain Aurorians can further decrease the time required to create Data Disks.",
  str_aircraft_desc_7111002 = "The Simulation Room is a special facility for Caelestites to improve their commanding skills. You can enter the Command Archives via the command simulator to simulate various environments and battles. The Simulation Room can <color=#00F6FF>create simulated combat scenarios and save the data on special disks</color>. Higher-level Simulation Rooms can <color=#00F6FF>increase the storage limit on Data Disks and decrease production times</color>. Certain Aurorians can further decrease the time required to create Data Disks.",
